@spec vm_snap_temper_spec  src=tests/specs/vm_snap_temper_spec.lua  loc=148  cases=8
@exercises tuning (tuning), trackerView (h.vm), editCursor (h.ec)
@surface   tuning.derive, vm:setGridSize, tuning.stepToMidi, vm:snapToTemper, ec:setSelection
@harness   mk{seed.notes}

# Intent
  Notation snap: tv:snapToTemper(scope, strength) runs every note in scope
  through tuning.snap and writes the pair back, strength being how far of the
  way there it actually lands. The temper is a twelve-note quarter-comma
  meantone MOS, so a step's seat carries a detune of its own and the window
  is asymmetric (+38.0 / -58.6 either side of step 1).

# Helpers
  @fn mk(harness, notes)  @ 17-24
  @fn note(ppq, pitch, detune)  @ 26-29
  @fn lane1(h)  @ 31-35
  @fn cell(h, row)  @ 37
  @fn near(a, b, msg)  @ 39-41
  @fn seat(step, oct)  @ 44
      -- Seat of (step, octave) under MEAN, as the spec's expectation frame.

# Cases
  @case 'snapToTemper(all) seats an off-step note on its own step'  [harness]  @ 48-57
  @case 'a note past the half-way point lands on its neighbour'  [harness]  @ 61-70
  @case 'a note inside the window keeps its step'  [harness]  @ 74-81
  @case 'a note already on its step is left where it is'  [harness]  @ 85-93
  @case 'a selection confines the snap to the notes inside it'  [harness]  @ 97-106
  @case 'half strength closes half the distance, and again on the next run'  [harness]  @ 110-120
  @case 'a blend below full strength is re-seated on the nearest semitone'  [harness]  @ 124-134
  @case 'zero strength moves nothing, not even the written pitch'  [harness]  @ 138-146

# Uses (outbound edges)
  @use call tuning.derive  @ 10
  @use call vm:setGridSize  @ 22
  @use call tuning.stepToMidi  @ 44
  @use call vm:snapToTemper  @ 51,65,77,89,102,115,117,129,142
  @use call ec:setSelection  @ 100

